from collections import deque

def dfs(root):
    order, stack = [], [root]
    while stack:
        node = stack.pop()                  # the NEWEST node first
        order.append(node.val)
        if node.right:
            stack.append(node.right)
        if node.left:
            stack.append(node.left)         # left on top: dive down the left first
    return order

def bfs(root):
    order, queue = [], deque([root])
    while queue:
        node = queue.popleft()              # the OLDEST node first
        order.append(node.val)
        if node.left:
            queue.append(node.left)
        if node.right:
            queue.append(node.right)
    return order

List<Integer> dfs(TreeNode root) {
    List<Integer> order = new ArrayList<>();
    Deque<TreeNode> stack = new ArrayDeque<>();
    stack.push(root);
    while (!stack.isEmpty()) {
        TreeNode node = stack.pop();        // the NEWEST node first
        order.add(node.val);
        if (node.right != null) stack.push(node.right);
        if (node.left != null) stack.push(node.left);   // left on top: dive down the left first
    }
    return order;
}

List<Integer> bfs(TreeNode root) {
    List<Integer> order = new ArrayList<>();
    Queue<TreeNode> queue = new ArrayDeque<>();
    queue.offer(root);
    while (!queue.isEmpty()) {
        TreeNode node = queue.poll();       // the OLDEST node first
        order.add(node.val);
        if (node.left != null) queue.offer(node.left);
        if (node.right != null) queue.offer(node.right);
    }
    return order;
}

vector<int> dfs(TreeNode* root) {
    vector<int> order;
    stack<TreeNode*> st;
    st.push(root);
    while (!st.empty()) {
        TreeNode* node = st.top();          // the NEWEST node first
        st.pop();
        order.push_back(node->val);
        if (node->right) st.push(node->right);
        if (node->left) st.push(node->left);    // left on top: dive down the left first
    }
    return order;
}

vector<int> bfs(TreeNode* root) {
    vector<int> order;
    queue<TreeNode*> q;
    q.push(root);
    while (!q.empty()) {
        TreeNode* node = q.front();         // the OLDEST node first
        q.pop();
        order.push_back(node->val);
        if (node->left) q.push(node->left);
        if (node->right) q.push(node->right);
    }
    return order;
}
